#[derive(Parser)]
struct Cli {
    #[arg(long, default_value = "http://127.0.0.1:8080")]
    server_url: String,

    #[arg(long, default_value_t = 4)]
    concurrency: usize,

    #[arg(long, default_value_t = 100)]
    warmup: usize,

    #[arg(long, default_value_t = 1000)]
    max_queries: usize,

    #[arg(long, default_value_t = 42)]
    seed: u64,

    #[arg(long, default_value = "/opt/vdb-data/query_vectors.json")]
    query_vectors: PathBuf,

    #[arg(long)]
    base_vectors: Option<PathBuf>,

    #[arg(long, default_value_t = 1000)]
    insert_batch_size: usize,

    #[arg(long, default_value_t = 0)]
    preload_max_vectors: usize,

    #[arg(long, value_enum, default_value_t = CompletionMode::Json)]
    completion_mode: CompletionMode,
}

#[derive(Clone, Copy, ValueEnum, Serialize)]
#[serde(rename_all = "snake_case")]
enum CompletionMode {
    Json,
    Bytes,
}

#[derive(Clone, Deserialize)]
struct IndexedVector {
    #[serde(default)]
    id: u64,
    vector: Vec<f32>,
}

#[derive(Clone, Serialize)]
struct SearchRequest {
    vector: Vec<f32>,
    top_k: u32,
}

#[derive(Deserialize)]
struct SearchResponse {
    results: Vec<SearchResult>,
}

#[derive(Deserialize)]
struct SearchResult {
    id: u64,
    distance: f64,
}

#[derive(Serialize)]
struct InsertItem {
    id: u64,
    vector: Vec<f32>,
}

#[derive(Serialize)]
struct BulkInsertRequest {
    vectors: Vec<InsertItem>,
}

#[derive(Deserialize)]
struct BulkInsertResponse {
    inserted: usize,
}

#[derive(Serialize)]
struct QueryTiming {
    ok: bool,
    send_ms: f64,
    body_ms: f64,
    total_ms: f64,
    send_completed_ms: f64,
    response_len: usize,
    results_len: usize,
}

#[derive(Serialize)]
struct MetricSummary {
    avg_ms: f64,
    p50_ms: f64,
    p95_ms: f64,
    p99_ms: f64,
    max_ms: f64,
}

#[derive(Serialize)]
struct PreloadSummary {
    vectors_loaded: usize,
    vectors_inserted: usize,
    batch_size: usize,
