use clap::Parser;
use std::time::Instant;

mod anti_cheat;
mod loader;
mod runner;
mod scorer;

#[derive(Parser)]
#[command(name = "vector-db-benchmark")]
#[command(about = "Benchmark client for Vector DB evaluation")]
struct Cli {
    /// Server URL
    #[arg(long, default_value = "http://127.0.0.1:8080")]
    server_url: String,

    /// Number of concurrent query threads
    #[arg(long, default_value_t = 4)]
    concurrency: usize,

    /// Number of warmup queries
    #[arg(long, default_value_t = 1000)]
    warmup: usize,

    /// Path to base vectors JSON file
    #[arg(long)]
    base_vectors: String,

    /// Path to query vectors JSON file
    #[arg(long)]
    query_vectors: String,

    /// Path to ground truth JSON file
    #[arg(long)]
    ground_truth: String,

    /// Recall threshold (0.0 to 1.0)
    #[arg(long, default_value_t = 0.95)]
    recall_threshold: f64,

    /// Random seed for query shuffling
    #[arg(long, default_value_t = 42)]
    seed: u64,

    /// Batch size for bulk insert
    #[arg(long, default_value_t = 1000)]
    batch_size: usize,

    /// Maximum number of queries to run (0 = all)
    #[arg(long, default_value_t = 0)]
    max_queries: usize,
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let cli = Cli::parse();
    let client = reqwest::Client::new();

    // 1. Load and insert base vectors
    eprintln!("Loading base vectors from {}...", cli.base_vectors);
    let base_vectors = loader::load_vectors_from_file(&cli.base_vectors).await?;
    eprintln!("Loaded {} base vectors, inserting...", base_vectors.len());
    let inserted = loader::bulk_insert_vectors(&client, &cli.server_url, &base_vectors, cli.batch_size).await?;
    eprintln!("Inserted {} vectors", inserted);

    // 2. Load query vectors and ground truth
    eprintln!("Loading query vectors from {}...", cli.query_vectors);
    let all_query_vectors = loader::load_vectors_from_file(&cli.query_vectors).await?;
    eprintln!("Loading ground truth from {}...", cli.ground_truth);
    let all_ground_truth = scorer::load_ground_truth(&cli.ground_truth).await?;

    // Apply max_queries limit if set
    let (query_vectors, ground_truth) = if cli.max_queries > 0 && cli.max_queries < all_query_vectors.len() {
        eprintln!("Limiting to {} queries (out of {})", cli.max_queries, all_query_vectors.len());
        let qv: Vec<_> = all_query_vectors.into_iter().take(cli.max_queries).collect();
        let gt: Vec<_> = all_ground_truth.into_iter().take(cli.max_queries).collect();
        (qv, gt)
    } else {
        (all_query_vectors, all_ground_truth)
    };

    // 3. Warmup
    eprintln!("Running {} warmup queries...", cli.warmup);
    runner::run_warmup(&client, &cli.server_url, &query_vectors, cli.warmup).await;

    // 4. Run benchmark queries
    eprintln!(
        "Running {} queries with concurrency {}...",
        query_vectors.len(),
        cli.concurrency
    );
    let start = Instant::now();
    let query_results = runner::run_queries(
        &client,
        &cli.server_url,
        &query_vectors,
        cli.concurrency,
        cli.seed,
    )
    .await;
    let duration_secs = start.elapsed().as_secs_f64();

    // 5. Compute results
    let result = scorer::compute_benchmark_result(
        &query_results,
        &ground_truth,
        duration_secs,
        cli.concurrency,
        cli.recall_threshold,
    );

    // 6. Anti-cheat detection
    let result_ids: Vec<Vec<u64>> = query_results
        .iter()
        .map(|qr| qr.results.iter().map(|r| r.id).collect())
        .collect();
    let anti_cheat = anti_cheat::detect_hardcoded_results(&result_ids);
    eprintln!("Anti-cheat: {}", anti_cheat.message);

    // 7. Output JSON to stdout
    let output = serde_json::json!({
        "benchmark": result,
        "anti_cheat": anti_cheat,
    });
    let json = serde_json::to_string_pretty(&output)?;
    println!("{}", json);

    Ok(())
}

use serde::{Deserialize, Serialize};
use std::sync::Arc;
use std::time::Instant;
use tokio::sync::Semaphore;

use rand::seq::SliceRandom;
use rand::SeedableRng;

use crate::loader::IndexedVector;

/// Request body for the `/search` endpoint.
#[derive(Debug, Clone, Serialize)]
pub struct SearchRequest {
    pub vector: Vec<f32>,
    pub top_k: u32,
}

/// A single search result returned by the server.
#[derive(Debug, Clone, Deserialize)]
pub struct SearchResult {
    pub id: u64,
    pub distance: f64,
}

/// Response from the `/search` endpoint.
#[derive(Debug, Clone, Deserialize)]
pub struct SearchResponse {
    pub results: Vec<SearchResult>,
}

/// Result of a single query, including latency and returned results.
#[derive(Debug, Clone)]
pub struct QueryResult {
    pub query_index: usize,
    pub results: Vec<SearchResult>,
    pub latency_ms: f64,
}

/// Send warmup queries to the server. Results are discarded.
pub async fn run_warmup(
    client: &reqwest::Client,
    server_url: &str,
    queries: &[IndexedVector],
    warmup_count: usize,
) {
    let url = format!("{}/search", server_url.trim_end_matches('/'));
    let count = warmup_count.min(queries.len());

    for q in queries.iter().take(count) {
        let req = SearchRequest {
            vector: q.vector.clone(),
            top_k: 10,
        };
        // Fire and forget – ignore errors during warmup.
        let _ = client.post(&url).json(&req).send().await;
    }
}

/// Run all queries concurrently with a semaphore-based concurrency limit.
///
/// The query order is shuffled deterministically using the provided `seed`.
/// Each query is sent as a POST `/search` request with `top_k=10`.
/// Returns a `QueryResult` for every query, preserving the original query index.
pub async fn run_queries(
    client: &reqwest::Client,
    server_url: &str,
    queries: &[IndexedVector],
    concurrency: usize,
    seed: u64,
) -> Vec<QueryResult> {
    let url = format!("{}/search", server_url.trim_end_matches('/'));

    // Build (original_index, query) pairs and shuffle deterministically.
    let mut indexed: Vec<(usize, &IndexedVector)> = queries.iter().enumerate().collect();
    let mut rng = rand::rngs::StdRng::seed_from_u64(seed);
    indexed.shuffle(&mut rng);

    let semaphore = Arc::new(Semaphore::new(concurrency));
    let client = client.clone();
    let url = Arc::new(url);

    let mut handles = Vec::with_capacity(indexed.len());

    for (idx, query) in indexed {
        let permit = semaphore.clone().acquire_owned().await.unwrap();
        let client = client.clone();
        let url = Arc::clone(&url);
        let vector = query.vector.clone();

        let handle = tokio::spawn(async move {
            let req = SearchRequest {
                vector,
                top_k: 10,
            };

            let start = Instant::now();
            let resp = client.post(url.as_str()).json(&req).send().await;
            let latency_ms = start.elapsed().as_secs_f64() * 1000.0;

            drop(permit);

            let results = match resp {
                Ok(r) => r
                    .json::<SearchResponse>()
                    .await
                    .map(|sr| sr.results)
                    .unwrap_or_default(),
                Err(_) => Vec::new(),
            };

            QueryResult {
                query_index: idx,
                results,
                latency_ms,
            }
        });

        handles.push(handle);
    }

    let mut results = Vec::with_capacity(handles.len());
    for handle in handles {
        if let Ok(qr) = handle.await {
            results.push(qr);
        }
    }

    results
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_search_request_serialize() {
        let req = SearchRequest {
            vector: vec![1.0, 2.0, 3.0],
            top_k: 10,
        };
        let json = serde_json::to_value(&req).unwrap();
        assert_eq!(json["top_k"], 10);
        assert_eq!(json["vector"].as_array().unwrap().len(), 3);
    }

    #[test]
    fn test_search_result_deserialize() {
        let json = r#"{"id": 42, "distance": 1.5}"#;
        let r: SearchResult = serde_json::from_str(json).unwrap();
        assert_eq!(r.id, 42);
        assert!((r.distance - 1.5).abs() < f64::EPSILON);
    }

    #[test]
    fn test_search_response_deserialize() {
        let json = r#"{"results": [{"id": 1, "distance": 0.5}, {"id": 2, "distance": 1.0}]}"#;
        let resp: SearchResponse = serde_json::from_str(json).unwrap();
        assert_eq!(resp.results.len(), 2);
        assert_eq!(resp.results[0].id, 1);
    }

    #[test]
    fn test_deterministic_shuffle() {
        let queries: Vec<IndexedVector> = (0..20)
            .map(|i| IndexedVector {
                id: i,
                vector: vec![i as f32],
            })
            .collect();

        let shuffle = |seed: u64| -> Vec<usize> {
            let mut indexed: Vec<(usize, &IndexedVector)> =
                queries.iter().enumerate().collect();
            let mut rng = rand::rngs::StdRng::seed_from_u64(seed);
            indexed.shuffle(&mut rng);
            indexed.iter().map(|(i, _)| *i).collect()
        };

        // Same seed → same order
        assert_eq!(shuffle(42), shuffle(42));
        // Different seed → different order (extremely unlikely to collide)
        assert_ne!(shuffle(42), shuffle(99));
    }
}

use serde::{Deserialize, Serialize};
use std::path::Path;

/// A vector with its ID, as stored in the JSON data files.
#[derive(Debug, Clone, Deserialize)]
pub struct IndexedVector {
    pub id: u64,
    pub vector: Vec<f32>,
}

/// A single item in a bulk insert request.
#[derive(Debug, Clone, Serialize)]
pub struct InsertItem {
    pub id: u64,
    pub vector: Vec<f32>,
}

/// Request body for the `/bulk_insert` endpoint.
#[derive(Debug, Serialize)]
pub struct BulkInsertRequest {
    pub vectors: Vec<InsertItem>,
}

/// Response from the `/bulk_insert` endpoint.
#[derive(Debug, Deserialize)]
pub struct BulkInsertResponse {
    pub status: String,
    pub inserted: usize,
}

/// Load base vectors from a JSON file.
///
/// The file should contain a JSON array of `{"id": u64, "vector": [f32; 128]}` objects.
pub async fn load_vectors_from_file(path: &str) -> Result<Vec<IndexedVector>, Box<dyn std::error::Error>> {
    let path = Path::new(path);
    let content = tokio::fs::read_to_string(path).await?;
    let vectors: Vec<IndexedVector> = serde_json::from_str(&content)?;
    Ok(vectors)
}

/// Bulk insert vectors into the server via HTTP POST `/bulk_insert`.
///
/// Vectors are split into batches of `batch_size` to avoid oversized request bodies.
/// Returns the total number of successfully inserted vectors.
pub async fn bulk_insert_vectors(
    client: &reqwest::Client,
    server_url: &str,
    vectors: &[IndexedVector],
    batch_size: usize,
) -> Result<usize, Box<dyn std::error::Error>> {
    let url = format!("{}/bulk_insert", server_url.trim_end_matches('/'));
    let mut total_inserted: usize = 0;

    for chunk in vectors.chunks(batch_size) {
        let items: Vec<InsertItem> = chunk
            .iter()
            .map(|v| InsertItem {
                id: v.id,
                vector: v.vector.clone(),
            })
            .collect();

        let request = BulkInsertRequest { vectors: items };

        let resp = client
            .post(&url)
            .json(&request)
            .send()
            .await?
            .error_for_status()?
            .json::<BulkInsertResponse>()
            .await?;

        total_inserted += resp.inserted;
    }

    Ok(total_inserted)
}

#[cfg(test)]
mod tests {
    use super::*;

